/**
 * 话题卡池（Topic Database）——**与 `frontend/src/data/topicDatabase.js` 逐字段一致**。
 *
 * 为什么要在这里再放一份：后端要能独立部署，不依赖前端源码目录。
 * 一致性由 `tests/topicDatabase.test.mjs` 保证：卡片数、id 集合、字段与取值逐项比对，
 * 前端改了卡池而后端没跟，`npm test` 立刻红。
 *
 * 契约 4.5 节：这一阶段按「双方兴趣优先 + 水平窗口 + 随机洗牌」从固定卡池里选卡，
 * 真 LLM 生成后置（接口形状不变，只换 `cards` 的来源）。
 */

