/**
 * 通用主题：**不属于任何一方的兴趣**、谁都能聊的题（13 个兴趣主题之外的那 7 个）。
 *
 * 唯一的用途是兜底：双方兴趣**交集为空**时（两个人一个兴趣都不重合），
 * 选卡器只从这里出卡——宁可给「今天天气点啊」这种谁都接得住的题，
 * 也不要退回**并集**（并集会把「只有其中一方感兴趣」的主题发出去，
 * 现场就是「这张卡跟我不相干」，2026-10-11 用户明确否掉）。
 *
 * 判据是「在不在 `INTERESTS` 里」（前端 `src/data/tags.js` / 后端 `src/data/vocabularies.js`），
 * 这里把它显式写出来，好让选卡器不必反向依赖词表。
 */
export const GENERAL_TOPICS = [
  'university',
  'sports',
  'daily_life',
  'weather',
  'work',
  'shopping',
  'festivals',
];

